func ResourceDesignCenterPolicyFlatten(d *schema.ResourceData, meta interface{}, res map[string]interface{}, config *transport_tpg.Config, project string, userAgent string, billingProject string, url string, headers http.Header) error {
	var err error

	if err = d.Set("name", flattenDesignCenterPolicyName(res["name"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("policy_type", flattenDesignCenterPolicyPolicyType(res["policyType"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("policy_uri", flattenDesignCenterPolicyPolicyUri(res["policyUri"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("policy_revision_uri", flattenDesignCenterPolicyPolicyRevisionUri(res["policyRevisionUri"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("display_name", flattenDesignCenterPolicyDisplayName(res["displayName"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("description", flattenDesignCenterPolicyDescription(res["description"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("apply_conditions", flattenDesignCenterPolicyApplyConditions(res["applyConditions"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("cloud_control_configs", flattenDesignCenterPolicyCloudControlConfigs(res["cloudControlConfigs"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("create_time", flattenDesignCenterPolicyCreateTime(res["createTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}
	if err = d.Set("update_time", flattenDesignCenterPolicyUpdateTime(res["updateTime"], d, config)); err != nil {
		return fmt.Errorf("Error reading Policy: %s", err)
	}

	return nil
}
